import copy
import json
from splunk.pdf.pdfgen_utils import getLogger

from splunk.pdf.studio.tokens import get_namespaced_tokens, replace_tokens_in_dict

logger = getLogger()


def is_search_ready_to_run(
    data_source: dict, already_handled: list = [], smart_source_data_sources: dict = {}
) -> bool:
    """if this search depends on another search's tokens it's not ready"""
    smart_source_tokens = get_namespaced_tokens(json.dumps(data_source))

    is_ready = True
    for token in smart_source_tokens:
        data_source_name = token.split(":")[0][1:]
        data_source_id = smart_source_data_sources.get(data_source_name)

        if data_source_id and not any(data_source_id in nested_list for nested_list in already_handled):
            is_ready = False
            break

    return is_ready


def get_searches_ready_to_run(data_sources: dict, search_grouping: list, valid_smart_sources: dict) -> list:
    """returns a list of data sources that don't depend on another search's smart source tokens"""
    next_batch = []
    for id in data_sources:
        if not is_search_ready_to_run(data_sources[id], search_grouping, valid_smart_sources):
            continue

        next_batch.append(id)

    return next_batch


def get_smart_source_data_sources(data_sources: dict) -> dict:
    """returns valid data sources. if a data source has the enableSmartSources option and a name it's valid"""
    valid_smart_sources = {}
    for data_source_id in data_sources:
        definition = data_sources[data_source_id]
        name = definition.get("name")
        if name is not None and definition.get("options", {}).get("enableSmartSources"):
            valid_smart_sources[name] = data_source_id

    return valid_smart_sources


def replace_smart_source_tokens(definition: dict, data_source_tokens):
    """replaces $SmartSource:Tokens$ with their resolved values"""
    resolved_smart_source_tokens = {}
    for data_source_id in data_source_tokens:
        tokens = data_source_tokens[data_source_id].get("smartSourceTokens")
        if tokens:
            resolved_smart_source_tokens.update(tokens)

    if resolved_smart_source_tokens:
        replace_tokens_in_dict(definition, resolved_smart_source_tokens)


def get_search_grouping(data_sources: dict) -> list:
    """
    returns an ordered list of grouped searches to handle dependent searches. e.g. if "ds_search" uses "$ds_first:job.sid$",
    we should wait for "ds_first" to finish before running "ds_search"

    example:
    [['ds_first'], ['ds_depend_on_first', 'ds_another'], ['ds_last]]
    """
    data_sources_copy = copy.deepcopy(data_sources)
    search_grouping = []

    # we don't want dozens of searches running synchronously
    max_chain = 10

    smart_source_data_sources = get_smart_source_data_sources(data_sources_copy)

    depth = 0
    while depth < max_chain:
        depth = depth + 1
        next_batch = get_searches_ready_to_run(data_sources_copy, search_grouping, smart_source_data_sources)
        if not next_batch:
            break

        for handled_data_source in next_batch:
            del data_sources_copy[handled_data_source]

        search_grouping.append(next_batch)

    remaining_searches = []
    for data_source in data_sources:
        if not any(data_source in nested_list for nested_list in search_grouping):
            remaining_searches.append(data_source)

    if remaining_searches:
        search_grouping.append(remaining_searches)

    return search_grouping
